questions.solution:
type Channel = "email" | "sms";
type Notifier = { send(to: string): string };

const builders: Record<Channel, () => Notifier> = {
  email: () => ({ send: (to) => `email to ${to}` }),
  sms: () => ({ send: (to) => `sms to ${to}` }),
};

function createNotifier(channel: string): Notifier {
  if (!Object.hasOwn(builders, channel)) throw new Error(`unknown channel: ${channel}`);
  return builders[channel as Channel]();
}

console.log(createNotifier("sms").send("0803"));
try {
  createNotifier("fax");
} catch (error) {
  console.log((error as Error).message);
}

