function startupCheck(table: Record<string, string>, secrets: Record<string, string | undefined>): string[] {
  const problems: string[] = [];
  for (const [country, provider] of Object.entries(table)) {
    if (!secrets[provider]) problems.push(`${country}: missing key for ${provider}`);
  }
  return problems;
}

console.log(startupCheck(routes, keys));

