questions.solution:
class Money {
  private constructor(readonly kobo: number) {}

  static fromKobo(kobo: number): Money {
    if (!Number.isSafeInteger(kobo) || kobo < 0) throw new Error("invalid amount");
    return new Money(kobo);
  }

  static fromNaira(naira: number): Money {
    if (!Number.isFinite(naira) || naira < 0) throw new Error("invalid amount");
    return Money.fromKobo(Math.round(naira * 100));
  }
}

console.log(Money.fromNaira(12.5).kobo, Money.fromKobo(1250).kobo);
try {
  Money.fromNaira(-3);
} catch (error) {
  console.log((error as Error).message);
}

