type Filter = { sql: string; value: string | boolean };

class TaskQuery {
  constructor(private readonly filters: readonly Filter[] = []) {}

  where(sql: string, value: string | boolean): TaskQuery {
    return new TaskQuery([...this.filters, { sql, value }]);
  }

  build(): { text: string; values: (string | boolean)[] } {
    const where = this.filters.map((f, i) => f.sql.replace("?", `$${i + 1}`)).join(" AND ");
    return { text: `SELECT * FROM tasks${where ? ` WHERE ${where}` : ""}`, values: this.filters.map((f) => f.value) };
  }
}

const open = new TaskQuery().where("done = ?", false);
const adas = open.where("owner = ?", "ada").build();
console.log(adas.text);
console.log(adas.values);
console.log(open.build().text);

