function once<T>(make: () => T): () => T {
  let created = false;
  let instance: T;
  return () => {
    if (!created) {
      instance = make();
      created = true;
    }
    return instance;
  };
}

let opened = 0;
const getPool = once(() => ({ id: ++opened }));
console.log(getPool() === getPool(), opened);

