interface Infrastructure {
  createStorage(): { put(key: string): void };
  createQueue(): { enqueue(job: string, key: string): void };
}

function upload(infra: Infrastructure, key: string): void {
  infra.createStorage().put(key);
  infra.createQueue().enqueue("thumbnail", key);
}

function testInfrastructure(log: string[]): Infrastructure {
  return {
    createStorage: () => ({ put: (key) => void log.push(`put ${key}`) }),
    createQueue: () => ({ enqueue: (job, key) => void log.push(`enqueue ${job} ${key}`) }),
  };
}

const log: string[] = [];
upload(testInfrastructure(log), "uploads/1.jpg");
console.log(log);
